    "questionBn": "উদ্দীপক: নদীর বিস্তার d = 400 m, স্রোতের বেগ u = 2 m/s, নৌকার বেগ v = 4 m/s। সোজাসুজি অপর পাড়ে পৌঁছাতে মাঝিকে কত কোণে নৌকা চালাতে হবে এবং এ ক্ষেত্রে পারাপারের সময় 90° কোণে পার হওয়ার চেয়ে বেশি না কম হবে গাণিতিক বিশ্লেষণ করো।",
