    "questionEn": "Explain why A × B = - (B × A).",
    "questionBn": "A × B = - (B × A) কেন হয়? ব্যাখ্যা করো।",
    "relevantFormulaLatex": "\\vec{A} \\times \\vec{B} = -(\\vec{B} \\times \\vec{A})",
    "hintEn": "Direction of cross product reverses when rotation order changes by right-hand thumb rule.",
    "hintBn": "ডানহাত নিয়ম অনুসারে ঘূর্ণনের দিক পরিবর্তন হলে লম্ব একক ভেক্টরের দিক উল্টে যায়।",
    "solutionStepsEn": [
      "Step 1: By definition, A × B = |A||B| sin θ η̂, where η̂ is a unit vector perpendicular to the plane of A and B given by the right-hand rule.",
      "Step 2: When rotating from B to A, the right-hand thumb points in the exact opposite direction: B × A = |B||A| sin θ (-η̂) = - (A × B).",
      "Step 3: Therefore, the cross product is anti-commutative: A × B = - (B × A)."
    ],
    "solutionStepsBn": [
      "ধাপ ১: ভেক্টর গুণনের সংজ্ঞানুসারে A × B = AB sin θ η̂, যেখানে η̂ হলো ডানহাতের স্ক্রু নিয়ম অনুসারে নির্ধারিত লম্ব একক ভেক্টর।",
      "ধাপ ২: B থেকে A-এর দিকে ডানহাতের আঙুল ঘোরালে বুড়ো আঙুল বিপরীত দিকে নির্দেশ করে, অর্থাৎ B × A = AB sin θ (-η̂) = -(A × B)।",
      "ধাপ ৩: সুতরাং ভেক্টর গুণন বিপরীত বিনিময় নিয়ম মানে।"
    ],
    "finalAnswerEn": "A × B = - (B × A) because the direction reverses under the right-hand thumb rule.",
