    "questionEn": "Two adjacent sides of a triangular garden are represented by vectors A = 3i - 2j + k and B = i + 3j - 2k. Find the area of the triangular garden.",
    "questionBn": "একটি ত্রিভুজাকার বাগানের দুটি সন্নিহিত বাহু যথাক্রমে A = 3i - 2j + k এবং B = i + 3j - 2k দ্বারা নির্দেশিত। বাগানটির ক্ষেত্রফল নির্ণয় করো।",
    "relevantFormulaLatex": "\\text{Area of Triangle} = \\frac{1}{2} |\\vec{A} \\times \\vec{B}|",
