    "questionBn": "উদ্দীপক: A = 3i - 2j + k এবং B = i + 3j - 2k। তৃতীয় ভেক্টর C = 2i + j - k। ভেক্টর তিনটি সমতলীয় কিনা গাণিতিকভাবে বিশ্লেষণ করো।",
