      "ধাপ ৩: 3(-3 + 2) - (-2)(-1 + 4) + 1(1 - 6) = 3(-1) + 2(3) - 5 = -3 + 6 - 5 = -2",
      "ধাপ ৪: যেহেতু A · (B × C) = -2 ≠ 0, তাই ভেক্টরত্রয় সমতলীয় নয়।"
