    "stemEn": "Coordinates of two points A and B are given below: A(2, 3, 1) and B(4, 2, -3) with respect to origin O(0,0,0). In triangle OAB, the angle between OA and OB is α.",
    "stemBn": "মূল বিন্দু O(০,০,০) এর সাপেক্ষে দুটি বিন্দুর স্থানাঙ্ক: A(২, ৩, ১) এবং B(৪, ২, -৩)। ত্রিভুজ OAB তে OA ও OB এর মধ্যবর্তী কোণ α।",
    "relevantFormulaLatex": "\\vec{OA} \\cdot \\vec{OB} = 0 \\lor \\vec{OA} \\cdot \\vec{AB} = 0 \\lor \\vec{OB} \\cdot \\vec{AB} = 0",
    "hintEn": "Check the dot product between all three pairs of vectors: OA, OB, and AB. If any dot product is zero, it is a right-angled triangle.",
    "hintBn": "OA, OB এবং AB এর মধ্যকার ডট গুণন অথবা পিথাগোরাসের উপপাদ্য প্রয়োগ করে যাচাই করো।",
    "solutionStepsEn": [
      "Step 1: Vectors forming the triangle: OA = 2i + 3j + 1k, OB = 4i + 2j - 3k, AB = 2i - 1j - 4k.",
      "Step 2: Compute squared side lengths: |OA|² = 2² + 3² + 1² = 14; |OB|² = 4² + 2² + (-3)² = 16 + 4 + 9 = 29; |AB|² = 2² + (-1)² + (-4)² = 4 + 1 + 16 = 21.",
      "Step 3: Test dot product OA · OB: OA · OB = (2)(4) + (3)(2) + (1)(-3) = 8 + 6 - 3 = 11 ≠ 0 (angle α ≠ 90°).",
      "Step 4: Test dot product OA · AB: OA · AB = (2)(2) + (3)(-1) + (1)(-4) = 4 - 3 - 4 = -3 ≠ 0.",
      "Step 5: Test dot product OB · AB: OB · AB = (4)(2) + (2)(-1) + (-3)(-4) = 8 - 2 + 12 = 18 ≠ 0.",
      "Step 6: Pythagorean check: Check if sum of any two squared lengths equals the third: 14 + 21 = 35 ≠ 29; 14 + 29 = 43 ≠ 21; 21 + 29 = 50 ≠ 14.",
      "Step 7: Conclusion: None of the three internal angles is 90°, and the side lengths do not satisfy the Pythagorean theorem. Therefore, ΔOAB does NOT form a right-angled triangle."
    ],
    "solutionStepsBn": [
      "ধাপ ১: বাহু ভেক্টরত্রয়: OA = ২i + ৩j + ১k, OB = ৪i + ২j - ৩k, AB = ২i - j - ৪k।",
      "ধাপ ২: বাহুগুলোর বর্গের মান: |OA|² = ১৪, |OB|² = ২৯, |AB|² = ২১।",
      "ধাপ ৩: ডট গুণন পরীক্ষা: OA · OB = (২)(৪) + (৩)(২) + (১)(-৩) = ১১ ≠ ০",
      "ধাপ ৪: OA · AB = (২)(২) + (৩)(-১) + (১)(-৪) = -৩ ≠ ০",
      "ধাপ ৫: OB · AB = (৪)(২) + (২)(-১) + (-৩)(-৪) = ১৮ ≠ ০",
      "ধাপ ৬: পিথাগোরাস পরীক্ষা: ১৪ + ২১ = ৩৫ ≠ ২৯ (|OB|² এর সমান নয়)।",
      "ধাপ ৭: সিদ্ধান্ত: কোনো কোণই ৯০° নয় এবং পিথাগোরাসের উপপাদ্য সিদ্ধ হয় না। সুতরাং ΔOAB একটি সমকোণী ত্রিভুজ নয়।"
    ],
    "finalAnswerEn": "No, ΔOAB does not form a right-angled triangle. None of the pairs are orthogonal (all dot products are non-zero: 11, -3, 18).",
    "finalAnswerBn": "না, ΔOAB সমকোণী ত্রিভুজ গঠন করবে না। কোনো বাহুদ্বয় পরস্পর লম্ব নয় (ডট গুণন যথাক্রমে ১১, -৩ এবং ১৮)।",
    "examinerMarkingTips": "Award 1 mark for side length squares (14, 29, 21), 2 marks for dot product/Pythagorean testing, and 1 mark for definitive conclusion.",
    "commonMistakes": "Only checking the angle at O and forgetting to check angles at vertices A and B.",
    "verificationStatus": "Verified Official Board Paper",
    "sourceReference": "Barishal Board 2017 (English Version), HSC Physics 1st Paper, Question 1(d).",
