    "stemEn": "According to the diagram, a river is 3 km wide. Two boats started from the same point A with the same engine speed v to cross the river. One is directed along AB (heading 30° upstream from the normal) and another one along AC (perpendicular to the bank). The first boat reached point C directly opposite after crossing, though the second boat reached point D. The velocity of the river current was 9 km/h.",
    "stemBn": "উদ্দীপকের চিত্রে ৩ কিমি প্রশস্ত একটি নদী। একই বিন্দু A হতে একই বেগে দুটি নৌকা নদী পার হওয়ার জন্য যাত্রা শুরু করল। একটি নৌকা AB বরাবর (অভিলম্বের সাথে ৩০° কোণে) এবং অপরটি AC বরাবর (তীরের লম্ব বরাবর) চালনা করা হলো। ১ম নৌকাটি সোজাসুজি অপর তীরের C বিন্দুতে এবং ২য় নৌকাটি D বিন্দুতে পৌঁছাল। স্রোতের বেগ ৯ কিমি/ঘণ্টা।",
