    "stemEn": "According to the diagram, a river is 3 km wide. Two boats started from the same point A with the same engine speed v to cross the river. One is directed along AB (heading 30° upstream from the normal) and another one along AC (perpendicular to the bank). The first boat reached point C directly opposite after crossing, though the second boat reached point D. The velocity of the river current was 9 km/h.",
    "stemBn": "উদ্দীপকের চিত্রে ৩ কিমি প্রশস্ত একটি নদী। একই বিন্দু A হতে একই বেগে দুটি নৌকা নদী পার হওয়ার জন্য যাত্রা শুরু করল। একটি নৌকা AB বরাবর (অভিলম্বের সাথে ৩০° কোণে) এবং অপরটি AC বরাবর (তীরের লম্ব বরাবর) চালনা করা হলো। ১ম নৌকাটি সোজাসুজি অপর তীরের C বিন্দুতে এবং ২য় নৌকাটি D বিন্দুতে পৌঁছাল। স্রোতের বেগ ৯ কিমি/ঘণ্টা।",
    "relevantFormulaLatex": "t_1 = \\frac{d}{v \\cos 30^\\circ}, \\quad t_2 = \\frac{d}{v \\sin 90^\\circ}",
    "hintEn": "Crossing time depends purely on the perpendicular velocity component across the river: vy = v cos 30° for Boat 1, and vy = v for Boat 2.",
    "hintBn": "তীরের লম্ব বরাবর কার্যকর বেগ বের করো: ১ম নৌকার vy1 = ১৮ cos ৩০°, ২য় নৌকার vy2 = ১৮ sin ৯০°। সময় t = d / vy তুলনা করো।",
    "solutionStepsEn": [
      "Step 1: Given river width d = 3 km, boat speed v = 18 km/h.",
      "Step 2: For Boat 1 (steered along AB at 30° to perpendicular): Crossing velocity vy1 = v cos 30° = 18 × 0.8660 = 15.588 km/h.",
      "Step 3: Crossing time for Boat 1: t₁ = d / vy1 = 3 / 15.588 = 0.1925 hours = 11.55 minutes (11 min 33 s).",
      "Step 4: For Boat 2 (steered along AC at 90° to bank): Crossing velocity vy2 = v sin 90° = 18 × 1 = 18.0 km/h.",
      "Step 5: Crossing time for Boat 2: t₂ = d / vy2 = 3 / 18 = 0.1667 hours = 10.00 minutes.",
      "Step 6: Comparison: t₂ = 10.0 min < t₁ = 11.55 min. Boat 2 crosses 1.55 minutes faster than Boat 1.",
      "Step 7: Conclusion: The two boats will NOT reach the other bank at the same time."
    ],
    "solutionStepsBn": [
      "ধাপ ১: নদীর প্রস্থ d = ৩ km, নৌকার বেগ v = ১৮ km/h।",
      "ধাপ ২: ১ম নৌকার উল্লম্ব বেগ: vy1 = ১৮ × cos ৩০° = ১৫.৫৯ km/h।",
      "ধাপ ৩: ১ম নৌকার সময়: t₁ = ৩ / ১৫.৫৯ = ০.১৯২৫ ঘণ্টা = ১১.৫৫ মিনিট (১১ মিনিট ৩৩ সেকেন্ড)।",
      "ধাপ ৪: ২য় নৌকার উল্লম্ব বেগ: vy2 = ১৮ × sin ৯০° = ১৮ km/h।",
      "ধাপ ৫: ২য় নৌকার সময়: t₂ = ৩ / ১৮ = ০.১৬৬৭ ঘণ্টা = ১০.০০ মিনিট।",
      "ধাপ ৬: তুলনা: t₂ (১০ মিনিট) < t₁ (১১.৫৫ মিনিট); অর্থাৎ ২য় নৌকাটি ১.৫৫ মিনিট আগে পৌঁছাবে।",
      "ধাপ ৭: সিদ্ধান্ত: নৌকা দুটি একই সময়ে অপর তীরে পৌঁছাবে না।"
    ],
    "finalAnswerEn": "No, the boats will not reach at the same time. Boat 2 reaches in 10.0 minutes, while Boat 1 takes 11.55 minutes (Boat 2 is 1.55 min faster).",
    "finalAnswerBn": "না, নৌকা দুটি একই সময়ে পৌঁছাবে না। ২য় নৌকাটি ১০ মিনিটে এবং ১ম নৌকাটি ১১.৫৫ মিনিটে পৌঁছাবে (২য় নৌকা ১.৫৫ মিনিট দ্রুত পার হবে)।",
    "examinerMarkingTips": "Award 1.5 marks for t1 calculation, 1.5 marks for t2 calculation, and 1 mark for clear comparative conclusion.",
    "commonMistakes": "Using the resultant speed for crossing time rather than the vertical component vy.",
