    "marks": 4,
    "difficulty": "Hard",
    "questionEn": "A river is 1 km wide. The current flows at u = 3 km/h. A boatman can row at v = 5 km/h in still water. (a) At what angle to the river flow should he steer to reach the bank directly opposite without drifting? (b) How long will it take, and what is his resultant speed?",
    "questionBn": "একটি নদী 1 km প্রশস্ত। নদীতে স্রোতের বেগ 3 km/h। স্থির পানিতে নৌকার বেগ 5 km/h। (ক) সোজাসুজি অপর পাড়ে পৌঁছাতে মাঝিকে স্রোতের সাথে কত কোণে নৌকা চালাতে হবে? (খ) নদী পার হতে কত সময় লাগবে এবং নৌকার লব্ধি বেগ কত?",
    "relevantFormulaLatex": "\\cos\\alpha = -\\frac{u}{v}, \\quad R = \\sqrt{v^2 - u^2}, \\quad t = \\frac{d}{R}",
    "hintEn": "To reach directly across (zero drift), the horizontal component of boat velocity must cancel the river flow: u + v cos α = 0. Then calculate R = √(v² - u²) and t = d / R.",
    "hintBn": "সোজাসুজি অপর পাড়ে যেতে u + v cos α = 0 হতে হবে। অর্থাৎ cos α = -u/v। এরপর লব্ধি বেগ R = √(v² - u²) এবং সময় t = d / R নির্ণয় করো।",
    "solutionStepsEn": [
      "Step 1: Condition for zero drift (landing directly opposite): cos α = -u / v = -3 / 5 = -0.6",
      "Step 2: Steering angle: α = arccos(-0.6) = 126.87° relative to the downstream current (or 36.87° upstream from perpendicular)",
      "Step 3: Resultant velocity directed straight across: R = √(v² - u²) = √(5² - 3²) = √(25 - 9) = √16 = 4 km/h",
      "Step 4: Crossing time: t = d / R = 1 km / 4 km/h = 0.25 hours = 15 minutes = 900 seconds"
    ],
    "solutionStepsBn": [
      "ধাপ ১: সোজাসুজি পৌঁছানোর শর্ত: cos α = -u / v = -3 / 5 = -0.6",
      "ধাপ ২: দিক: α = cos⁻¹(-0.6) = 126.87°",
      "ধাপ ৩: লব্ধি বেগ: R = √(5² - 3²) = √16 = 4 km/h",
      "ধাপ ৪: প্রয়োজনীয় সময়: t = d / R = 1 / 4 h = 15 মিনিট।"
    ],
    "finalAnswerEn": "Steering angle α = 126.87°; Resultant speed R = 4 km/h; Crossing time t = 15 minutes (0.25 h).",
    "finalAnswerBn": "নৌকা চালানোর কোণ α = 126.87°, লব্ধি বেগ 4 km/h, সময় 15 মিনিট।",
    "examinerMarkingTips": "1 mark for cos α = -u/v, 1 mark for angle 126.87°, 1 mark for resultant speed R = 4 km/h, 1 mark for crossing time with units.",
