    "questionEn": "Which one is greater between θ₁ (angle between OB and OC) and θ₂ (angle between OB and OA)? Explain mathematically using the stem.",
    "questionBn": "θ₁ (OB ও OC এর মধ্যবর্তী কোণ) এবং θ₂ (OB ও OA এর মধ্যবর্তী কোণ) এর মধ্যে কোনটি বৃহত্তর? উদ্দীপকের আলোকে গাণিতিকভাবে ব্যাখ্যা করো।",
    "stemEn": "In the figure, OABC is a rectangle. OA and OB represent the vectors P = i - 2j - k and Q = 2i - 3j + 2k respectively.",
    "stemBn": "চিত্রে OABC একটি আয়তক্ষেত্র। OA এবং OB যথাক্রমে ভেক্টর P = i - 2j - k এবং Q = 2i - 3j + 2k নির্দেশ করে।",
    "relevantFormulaLatex": "\\cos\\theta_2 = \\frac{\\vec{P} \\cdot \\vec{Q}}{|P||Q|}, \\quad \\theta_1 + \\theta_2 = 90^\\circ",
    "hintEn": "Find θ2 between OA (P) and OB (Q) using dot product. Since OABC is a rectangle, angle AOC = 90°, so θ1 = 90° - θ2.",
    "hintBn": "P ও Q এর ডট গুণন হতে θ2 বের করো। যেহেতু OABC আয়তক্ষেত্র, তাই θ1 + θ2 = ৯০°।",
    "solutionStepsEn": [
      "Step 1: Compute dot product P · Q = (1)(2) + (-2)(-3) + (-1)(2) = 2 + 6 - 2 = 6",
      "Step 2: Magnitudes: |P| = √(1² + (-2)² + (-1)²) = √6 ≈ 2.4495; |Q| = √(2² + (-3)² + 2²) = √17 ≈ 4.1231",
      "Step 3: Compute cos θ₂: cos θ₂ = (P · Q) / (|P||Q|) = 6 / (√6 × √17) = 6 / √102 = 6 / 10.0995 ≈ 0.5941",
      "Step 4: Angle θ₂ between OB and OA: θ₂ = arccos(0.5941) ≈ 53.55°",
      "Step 5: In rectangle OABC, the corner angle AOC = 90°. Since OB lies between OA and OC: θ₁ + θ₂ = 90°",
      "Step 6: Compute θ₁: θ₁ = 90° - 53.55° = 36.45°",
      "Step 7: Comparison: θ₂ (53.55°) > θ₁ (36.45°). Therefore, θ₂ is greater than θ₁."
    ],
    "solutionStepsBn": [
      "ধাপ ১: ডট গুণন: P · Q = (১)(২) + (-২)(-৩) + (-১)(২) = ২ + ৬ - ২ = ৬",
      "ধাপ ২: মান: |P| = √৬ = ২.৪৫; |Q| = √১৭ = ৪.১২",
      "ধাপ ৩: cos θ₂ = ৬ / (√৬ × √১৭) = ৬ / ১০.১ = ০.৫৯৪১",
      "ধাপ ৪: θ₂ = cos⁻¹(০.৫৯৪১) = ৫৩.৫৫°",
      "ধাপ ৫: আয়তক্ষেত্র হওয়ায় কোণ AOC = ৯০°, ফলে θ₁ + θ₂ = ৯০° => θ₁ = ৯০° - ৫৩.৫৫° = ৩৬.৪৫°",
      "ধাপ ৬: তুলনা: θ₂ (৫৩.৫৫°) > θ₁ (৩৬.৪৫°); অতএব θ₂ বৃহত্তর।"
    ],
    "finalAnswerEn": "θ₂ is greater than θ₁ (θ₂ = 53.55° vs θ₁ = 36.45°).",
    "finalAnswerBn": "θ₂ এর মান θ₁ অপেক্ষা বৃহত্তর (θ₂ = ৫৩.৫৫° এবং θ₁ = ৩৬.৪৫°)।",
    "examinerMarkingTips": "Award 1 mark for dot product calculation, 1 mark for θ2 = 53.55°, 1 mark for using geometric property θ1 + θ2 = 90° to find θ1 = 36.45°, and 1 mark for comparison.",
    "commonMistakes": "Forgetting that OABC is a rectangle and failing to relate θ1 and θ2.",
