    "stemEn": "A boat is crossing a river from point A along AD where the river is 2.5 km wide. Boat's velocity in calm water is v = (3i + 3j) m/s and velocity of current is u = 2i m/s. In another case, the boat goes along AB (perpendicular to bank) with the same speed.",
    "stemBn": "২.৫ কিমি প্রশস্ত একটি নদীতে একটি নৌকা A বিন্দু হতে AD বরাবর চালনা করা হলো। স্থির পানিতে নৌকার বেগ v = (৩i + ৩j) m/s এবং স্রোতের বেগ u = ২i m/s। অপর ক্ষেত্রে নৌকাটি একই দ্রুতিতে AB (তীরের লম্ব) বরাবর চালানো হলো।",
    "relevantFormulaLatex": "W = \\int \\vec{F}_s \\cdot d\\vec{x} = \\int (-kx) dx = -\\frac{1}{2} k x^2 < 0",
    "hintEn": "Restoring force opposes displacement from equilibrium. When displaced away from mean position, force and displacement point in opposite directions.",
