      "ধাপ ২: যখন কোনো বস্তুকে সাম্যাবস্থা হতে বাইরের দিকে টেনে নেওয়া হয় (প্রসারিত বা সংকুচিত করা হয়), তখন সরণ ঘটে বাইরের দিকে আর প্রত্যয়নী বল কাজ করে ভেতরের দিকে।",
