    "hintBn": "নদীর প্রস্থ d = ২৫০০ m। পারাপারের সময় নির্ভর করে j উপাংশের ওপর। ১ম ক্ষেত্রে vy1 = ৩ m/s। ২য় ক্ষেত্রে পুরো দ্রুতি √১৮ m/s লম্ব বরাবর।",
