    "stemEn": "At the same time, three forces are acting on a body of mass m = 10 kg: 8 N North, 2 N South, and 8 N East as shown in Figure-1. In Figure-2, the body moves with acceleration a = 1 m/s² at an angle of 36.87° North of East.",
    "stemBn": "একই সময়ে m = ১০ kg ভরের একটি বস্তুর ওপর তিনটি বল ক্রিয়াশীল: ৮ N উত্তর, ২ N দক্ষিণ এবং ৮ N পূর্ব (চিত্র-১ এ প্রদর্শিত)। চিত্র-২ এ বস্তুটি পূর্বের সাথে ৩৬.৮৭° কোণে a = ১ m/s² ত্বরণে গতিশীল।",
