    "questionType": "CQ_Ga",
    "marks": 3,
    "difficulty": "Medium",
    "questionEn": "Given vectors A = 2i - j + k and B = 3i + 2j - 4k. Find a unit vector perpendicular to both vectors A and B.",
    "questionBn": "A = 2i - j + k এবং B = 3i + 2j - 4k দেওয়া আছে। A ও B উভয়ের উপর লম্ব একটি একক ভেক্টর নির্ণয় করো।",
    "relevantFormulaLatex": "\\hat{\\eta} = \\pm \\frac{\\vec{A} \\times \\vec{B}}{|\\vec{A} \\times \\vec{B}|}",
    "hintEn": "Take the cross product A × B, compute its magnitude, and divide the cross product by its magnitude. Don't forget the ± symbol.",
    "hintBn": "A × B নির্ণয় করে তার মান দিয়ে ভাগ করো। আগে ± চিহ্ন দিতে ভুলবে না।",
    "solutionStepsEn": [
      "Step 1: Compute A × B: | i  j  k ; 2 -1  1 ; 3  2 -4 |",
      "Step 2: i-component: (-1)(-4) - (1)(2) = 4 - 2 = 2",
      "Step 3: j-component: -[(2)(-4) - (1)(3)] = -[-8 - 3] = +11",
      "Step 4: k-component: (2)(2) - (-1)(3) = 4 + 3 = 7",
      "Step 5: A × B = 2i + 11j + 7k",
      "Step 6: Magnitude: |A × B| = √(2² + 11² + 7²) = √(4 + 121 + 49) = √174 ≈ 13.19",
      "Step 7: Unit normal vector: η̂ = ± (2i + 11j + 7k) / √174"
    ],
