    "marks": 4,
    "difficulty": "Hard",
    "languageVersion": "Bangla Version",
    "questionEn": "Stem: A = 2i - 3j + k and B = i + 2j - 3k. A third vector is C = 3i - j - 2k. Determine mathematically whether vectors A, B, and C can form the three concurrent edges of a solid box (parallelepiped), and calculate its volume.",
    "questionBn": "উদ্দীপক: A = 2i - 3j + k এবং B = i + 2j - 3k। তৃতীয় ভেক্টর C = 3i - j - 2k। ভেক্টর তিনটি একটি ঘনবস্তু (সামান্তরিকীয় ঘনক)-এর তিনটি সন্নিহিত ধার গঠন করতে পারে কিনা এবং এর আয়তন কত হবে গাণিতিক বিশ্লেষণ করো।",
    "relevantFormulaLatex": "V = |\\vec{A} \\cdot (\\vec{B} \\times \\vec{C})|",
    "hintEn": "Calculate the scalar triple product. If volume V > 0, they form a solid 3D box.",
    "hintBn": "স্কেলার ট্রিপল গুণফল A · (B × C) নির্ণয় করো। আয়তন V > 0 হলে ঘনবস্তু গঠন করবে।",
    "solutionStepsEn": [
      "Step 1: Parallelepiped volume is V = |A · (B × C)|.",
      "Step 2: Determinant: | 2 -3  1 ; 1  2 -3 ; 3 -1 -2 |",
      "Step 3: Expand: 2[(2)(-2) - (-3)(-1)] - (-3)[(1)(-2) - (-3)(3)] + 1[(1)(-1) - (2)(3)]",
      "Step 4: 2[-4 - 3] + 3[-2 + 9] + 1[-1 - 6] = 2(-7) + 3(7) + 1(-7) = -14 + 21 - 7 = 0",
      "Step 5: Since the scalar triple product is exactly 0, the volume is zero (V = 0).",
      "Step 6: Conclusion: Because V = 0, vectors A, B, and C are coplanar and cannot form a 3D solid box."
    ],
    "solutionStepsBn": [
      "ধাপ ১: ঘনকের আয়তন V = |A · (B × C)|",
      "ধাপ ২: নির্ণায়ক: | 2 -3  1 ; 1  2 -3 ; 3 -1 -2 |",
      "ধাপ ৩: 2(-4 - 3) + 3(-2 + 9) + 1(-1 - 6) = 2(-7) + 3(7) - 7 = -14 + 21 - 7 = 0",
      "ধাপ ৪: যেহেতু আয়তন V = 0, তাই ভেক্টরত্রয় একই সমতলে অবস্থিত (সমতলীয়)।",
      "ধাপ ৫: সুতরাং তারা ত্রিমাত্রিক ঘনবস্তু গঠন করতে পারবে না।"
    ],
    "finalAnswerEn": "Volume V = 0 cubic units. The vectors are coplanar and cannot form a solid 3D box.",
    "finalAnswerBn": "আয়তন V = 0 ঘন একক। ভেক্টর তিনটি সমতলীয় হওয়ায় তারা কোনো ত্রিমাত্রিক ঘনবস্তু গঠন করতে পারে না।",
    "examinerMarkingTips": "2 marks for determinant expansion yielding 0, 2 marks for stating V = 0 means coplanar so no 3D box is formed.",
    "commonMistakes": "Not taking absolute value for volume or failing to conclude coplanarity.",
