    "difficulty": "Hard",
    "languageVersion": "Bangla Version",
    "questionEn": "Stem: F = (x + 3y)i + (y - 2z)j + (x + bz)k. When b = -2 (making F solenoidal), determine mathematically whether the vector field F is also irrotational (rot F = 0).",
    "questionBn": "উদ্দীপক: F = (x + 3y)i + (y - 2z)j + (x + bz)k। b = -2 হলে (যখন ক্ষেত্রটি সলিনয়ডাল), ভেক্টর ক্ষেত্রটি অঘূর্ণনশীল (rot F = 0) কিনা গাণিতিক যাচাই করো।",
    "relevantFormulaLatex": "\\text{curl } \\vec{F} = \\nabla \\times \\vec{F} = \\vec{0}",
    "hintEn": "Set up the curl determinant with F = (x + 3y)i + (y - 2z)j + (x - 2z)k and evaluate.",
    "hintBn": "কার্লের নির্ণায়ক বিস্তার করো: i(∂Fz/∂y - ∂Fy/∂z) - j(...) + k(...)।",
    "solutionStepsEn": [
      "Step 1: With b = -2, F = (x + 3y)i + (y - 2z)j + (x - 2z)k.",
      "Step 2: Curl determinant: ∇ × F = | i  j  k ; ∂/∂x  ∂/∂y  ∂/∂z ; (x+3y)  (y-2z)  (x-2z) |",
      "Step 3: i-component: ∂/∂y(x - 2z) - ∂/∂z(y - 2z) = 0 - (-2) = +2",
      "Step 4: j-component: -[ ∂/∂x(x - 2z) - ∂/∂z(x + 3y) ] = -[ 1 - 0 ] = -1",
      "Step 5: k-component: ∂/∂x(y - 2z) - ∂/∂y(x + 3y) = 0 - 3 = -3",
      "Step 6: ∇ × F = 2i - j - 3k ≠ 0.",
      "Step 7: Conclusion: Since curl F ≠ 0, the vector field is NOT irrotational (it is rotational)."
    ],
    "solutionStepsBn": [
      "ধাপ ১: b = -2 হলে F = (x + 3y)i + (y - 2z)j + (x - 2z)k",
      "ধাপ ২: ∇ × F = | i  j  k ; ∂/∂x  ∂/∂y  ∂/∂z ; (x+3y) (y-2z) (x-2z) |",
      "ধাপ ৩: i(0 - (-2)) - j(1 - 0) + k(0 - 3) = 2i - j - 3k",
      "ধাপ ৪: যেহেতু ∇ × F = 2i - j - 3k ≠ 0, তাই ক্ষেত্রটি অঘূর্ণনশীল নয় (ঘূর্ণনশীল)।"
    ],
    "finalAnswerEn": "∇ × F = 2i - j - 3k ≠ 0. The vector field is rotational (NOT irrotational).",
    "finalAnswerBn": "∇ × F = 2i - j - 3k ≠ 0 হওয়ায় ভেক্টর ক্ষেত্রটি অঘূর্ণনশীল নয় (ঘূর্ণনশীল)।",
    "examinerMarkingTips": "2 marks for curl evaluation giving 2i - j - 3k, 2 marks for stating curl ≠ 0 so field is rotational.",
    "commonMistakes": "Sign errors in evaluating ∂/∂z(y - 2z) = -2.",
    "verificationStatus": "Curriculum Practice Standard",
    "sourceReference": "NCTB Model Curriculum Standard 2020, Paper 1, Question 2(d).",
    "solutionVerified": true
