    "questionEn": "Explain why the scalar triple product represents the volume of a parallelepiped.",
    "questionBn": "স্কেলার ট্রিপল গুণফল একটি সামান্তরিকীয় ঘনকের আয়তন নির্দেশ করে কেন? ব্যাখ্যা করো।",
    "relevantFormulaLatex": "V = |\\vec{A} \\cdot (\\vec{B} \\times \\vec{C})| = (\\text{Base Area}) \\times (\\text{Height})",
    "hintEn": "|B × C| is base area, and A · η̂ is perpendicular height.",
    "hintBn": "|B × C| ভূমির ক্ষেত্রফল এবং A cos θ হলো লম্ব উচ্চতা।",
    "solutionStepsEn": [
      "Step 1: The cross product |B × C| equals the area of the base parallelogram formed by vectors B and C.",
      "Step 2: The unit vector normal to the base is η̂ = (B × C)/|B × C|.",
      "Step 3: The perpendicular height of the parallelepiped is the projection of A along η̂: h = |A| cos θ = A · η̂.",
      "Step 4: Volume = Base Area × Height = |B × C| × [A · (B × C) / |B × C|] = |A · (B × C)|."
    ],
    "solutionStepsBn": [
      "ধাপ ১: |B × C| হলো ভেক্টর B ও C দ্বারা গঠিত সামান্তরিক ভূমির ক্ষেত্রফল।",
      "ধাপ ২: ভূমির ওপর লম্ব একক ভেক্টর η̂-এর দিকে ভেক্টর A-এর লম্ব অভিক্ষেপই হলো ঘনকের উচ্চতা h = |A| cos θ।",
      "ধাপ ৩: আয়তন = ভূমির ক্ষেত্রফল × উচ্চতা = |B × C| × (|A| cos θ) = |A · (B × C)|।"
    ],
    "finalAnswerEn": "Because |B × C| gives base area and A · η̂ gives perpendicular height, their product yields the 3D volume.",
    "finalAnswerBn": "|B × C| ভূমির ক্ষেত্রফল এবং এর ওপর A-এর অভিক্ষেপ লম্ব উচ্চতা নির্দেশ করায় তাদের গুণফল আয়তন নির্দেশ করে।",
    "examinerMarkingTips": "1 mark for base area |B × C|, 1 mark for height projection and product.",
    "commonMistakes": "Not explaining the height projection.",
