    "difficulty": "Hard",
    "languageVersion": "Bangla Version",
    "questionEn": "Stem: River current u = 4 km/h, swimmer speed v = 8 km/h. If during monsoons the current speed increases to u' = 10 km/h while the swimmer speed remains 8 km/h, will the swimmer be able to reach the bank directly opposite? Analyze mathematically.",
    "questionBn": "উদ্দীপক: নদীতে স্রোতের বেগ 4 km/h এবং সাঁতারুর বেগ 8 km/h। বর্ষাকালে স্রোতের বেগ বৃদ্ধি পেয়ে 10 km/h হলে এবং সাঁতারুর বেগ 8 km/h থাকলে তিনি সোজাসুজি অপর পাড়ে পৌঁছাতে পারবেন কি? গাণিতিক মতামত দাও।",
    "relevantFormulaLatex": "\\cos\\alpha = -\\frac{u'}{v} = -\\frac{10}{8} = -1.25 \\implies \\text{No real angle}",
    "hintEn": "Check whether cos α = -u/v can be satisfied when u > v.",
    "hintBn": "সোজাসুজি যাওয়ার শর্ত cos α = -u/v যাচাই করো যখন u > v।",
    "solutionStepsEn": [
      "Step 1: Condition for zero drift (reaching directly opposite point B): u' + v cos α = 0  ==>  cos α = -u' / v.",
      "Step 2: Here u' = 10 km/h and v = 8 km/h: cos α = -10 / 8 = -1.25.",
      "Step 3: For all real angles α, -1 ≤ cos α ≤ 1. The value -1.25 is outside this domain.",
      "Step 4: Since |cos α| > 1, no real angle α exists that can neutralize the river current.",
      "Step 5: Conclusion: The swimmer will inevitably be swept downstream and CANNOT reach the directly opposite bank."
    ],
    "solutionStepsBn": [
      "ধাপ ১: সোজাসুজি অপর পাড়ে পৌঁছানোর শর্ত: u' + v cos α = 0  ==>  cos α = -u' / v",
      "ধাপ ২: মান বসিয়ে: cos α = -10 / 8 = -1.25",
      "ধাপ ৩: কিন্তু যেকোনো বাস্তব কোণ α এর জন্য cos α এর মান -1 অপেক্ষা ছোট হতে পারে না (-1 ≤ cos α ≤ 1)।",
      "ধাপ ৪: যেহেতু cos α = -1.25 অসম্ভব, তাই সাঁতারু কোনো কোণেই স্রোতের বেগ নিষ্ক্রিয় করতে পারবে না।",
      "ধাপ ৫: সিদ্ধান্ত: সাঁতারু সোজাসুজি অপর পাড়ে পৌঁছাতে পারবেন না।"
    ],
    "finalAnswerEn": "No; cos α = -1.25 has no real mathematical solution because |cos α| ≤ 1. The swimmer cannot reach directly opposite.",
    "finalAnswerBn": "না; cos α = -1.25 অবাস্তব হওয়ায় সাঁতারু কোনোভাবেই সোজাসুজি অপর পাড়ে পৌঁছাতে পারবেন না।",
    "examinerMarkingTips": "2 marks for deriving cos α = -1.25, 2 marks for stating domain constraint |cos α| ≤ 1 and drawing correct conclusion.",
    "commonMistakes": "Trying to force an angle calculation using arccos(-1.25) on a calculator without noticing domain error.",
