    "questionEn": "Can three forces of magnitudes 3 N, 4 N, and 8 N keep a particle in equilibrium? Explain.",
    "questionBn": "3 N, 4 N এবং 8 N মানের তিনটি বল কি একটি কণিকাকে সাম্যাবস্থায় রাখতে পারে? ব্যাখ্যা করো।",
    "relevantFormulaLatex": "|P - Q| \\le R \\le P + Q \\implies 8 \\le 3 + 4 = 7 \\quad (\\text{False})",
