      "ধাপ ২: ত্রিভুজ সূত্রানুযায়ী যেকোনো দুই বাহুর সমষ্টি তৃতীয় বাহু অপেক্ষা বৃহত্তর হতে হয়: 3 + 4 = 7 < 8।",
