    "questionEn": "Stem: River width d = 500 m, current speed u = 3 m/s. Kabir rows at v = 5 m/s directly perpendicular to the bank (α = 90°). Calculate the downstream distance Kabir drifts upon reaching the opposite bank.",
    "questionBn": "উদ্দীপক: নদীর বিস্তার d = 500 m, স্রোতের বেগ u = 3 m/s। কবির তীরের সাথে লম্বভাবে (α = 90°) v = 5 m/s বেগে নৌকা চালাল। অপর পাড়ে পৌঁছাতে কবির ভাটির দিকে কত দূরে ভেসে যাবে?",
    "relevantFormulaLatex": "t = \\frac{d}{v}, \\quad x = u \\cdot t",
    "hintEn": "Time t = 500 / 5 = 100 s; drift x = u × t.",
