    "relevantFormulaLatex": "\\frac{d\\phi}{ds} = \\nabla\\phi \\cdot \\hat{u} = |\\nabla\\phi| \\cos\\theta \\implies \\left(\\frac{d\\phi}{ds}\\right)_{\\max} = |\\nabla\\phi| \\text{ when } \\theta = 0^\\circ",
    "hintEn": "Directional derivative is ∇φ · û = |∇φ| cos θ, maximum when cos θ = 1.",
    "hintBn": "দিকস্থ অন্তরজ ∇φ · û = |∇φ| cos θ; θ = 0° হলে এর মান সর্বোচ্চ হয়।",
    "solutionStepsEn": [
      "Step 1: The rate of change of φ in any direction defined by unit vector û is the directional derivative: dφ/ds = ∇φ · û = |∇φ| cos θ.",
      "Step 2: Here θ is the angle between ∇φ and the direction û.",
      "Step 3: Since cos θ has its maximum value of 1 when θ = 0°, the rate of increase is maximized when û is parallel to ∇φ.",
      "Step 4: Therefore, ∇φ points in the direction of the steepest ascent, and its magnitude |∇φ| equals that maximum rate of change."
    ],
    "solutionStepsBn": [
      "ধাপ ১: একক ভেক্টর û বরাবর φ-এর পরিবর্তনের হার হলো দিকস্থ অন্তরজ: dφ/ds = ∇φ · û = |∇φ| cos θ।",
      "ধাপ ২: এখানে θ হলো ∇φ এবং û এর মধ্যবর্তী কোণ।",
      "ধাপ ৩: cos θ-এর মান সর্বোচ্চ (1) হয় যখন θ = 0°, অর্থাৎ û এবং ∇φ একই দিকে থাকে।",
      "ধাপ ৪: সুতরাং ∇φ ভেক্টরটি স্কেলার ক্ষেত্রের সর্বাধিক বৃদ্ধির দিক নির্দেশ করে এবং এর মান সর্বাধিক পরিবর্তনের হারের সমান।"
    ],
    "finalAnswerEn": "Directional derivative |∇φ| cos θ is maximized when θ = 0°, proving ∇φ points in the direction of steepest increase.",
    "finalAnswerBn": "দিকস্থ অন্তরজের মান θ = 0° কোণে সর্বোচ্চ হওয়ায় গ্রেডিয়েন্ট সর্বাধিক বৃদ্ধির দিক ও হার নির্দেশ করে।",
    "examinerMarkingTips": "1 mark for directional derivative formula |∇φ| cos θ, 1 mark for maximum at θ = 0°.",
