    "questionType": "CQ_Ga",
    "marks": 3,
    "difficulty": "Medium",
    "questionEn": "The diagonals of a parallelogram are given by D1 = 3i + 2j - k and D2 = i - 3j + 4k. Calculate the area of the parallelogram.",
    "questionBn": "একটি সামান্তরিকের দুটি কর্ণ D1 = 3i + 2j - k এবং D2 = i - 3j + 4k। সামান্তরিকটির ক্ষেত্রফল নির্ণয় করো।",
    "relevantFormulaLatex": "\\text{Area of Parallelogram with diagonals } D_1, D_2 = \\frac{1}{2} |\\vec{D}_1 \\times \\vec{D}_2|",
    "hintEn": "When DIAGONALS are given (not adjacent sides), the area is ½ |D1 × D2|.",
    "hintBn": "যদি সন্নিহিত বাহুর বদলে কর্ণ দেওয়া থাকে, তবে ক্ষেত্রফল = ½ |D1 × D2|।",
    "solutionStepsEn": [
      "Step 1: Compute cross product D1 × D2: | i  j  k ; 3  2 -1 ; 1 -3  4 |",
      "Step 2: i-component: (2)(4) - (-1)(-3) = 8 - 3 = 5",
      "Step 3: j-component: -[(3)(4) - (-1)(1)] = -[12 + 1] = -13",
      "Step 4: k-component: (3)(-3) - (2)(1) = -9 - 2 = -11",
      "Step 5: D1 × D2 = 5i - 13j - 11k",
      "Step 6: Magnitude: |D1 × D2| = √(5² + (-13)² + (-11)²) = √(25 + 169 + 121) = √315 ≈ 17.748",
      "Step 7: Area = ½ |D1 × D2| = 0.5 × 17.748 = 8.874 sq. units"
    ],
    "solutionStepsBn": [
      "ধাপ ১: D1 × D2 = 5i - 13j - 11k",
      "ধাপ ২: মান = √(25 + 169 + 121) = √315 ≈ 17.75",
      "ধাপ ৩: ক্ষেত্রফল = ½ |D1 × D2| = 8.87 বর্গ একক।"
    ],
    "finalAnswerEn": "Area of the parallelogram = ½ √315 ≈ 8.87 sq. units.",
    "finalAnswerBn": "সামান্তরিকের ক্ষেত্রফল 8.87 বর্গ একক।",
    "examinerMarkingTips": "Award 1 mark for cross product, 1 mark for magnitude, 1 mark for ½ factor and final answer.",
