    "questionEn": "Stem: River width d = 750 m, current speed u = 2.5 m/s, motorboat speed v = 5 m/s. Calculate the minimum time required to cross the river and the downstream drift distance under this condition.",
    "questionBn": "উদ্দীপক: নদীর বিস্তার d = 750 m, স্রোতের বেগ u = 2.5 m/s, মোটরবোটের বেগ v = 5 m/s। নদী পার হতে সর্বনিম্ন কত সময় লাগবে এবং এ ক্ষেত্রে বোটটি ভাটির দিকে কত দূরে ভেসে যাবে?",
    "relevantFormulaLatex": "t_{\\min} = \\frac{d}{v}, \\quad x = u \\cdot t_{\\min}",
