    "hintBn": "ন্যূনতম সময়ের জন্য α = 90°; t_min = 750 / 5 = 150 s; অপসরণ = 2.5 × 150।",
    "solutionStepsEn": [
      "Step 1: Minimum crossing time occurs at steering angle α = 90°: t_min = d / v = 750 m / 5 m/s = 150 seconds (2.5 minutes).",
      "Step 2: At α = 90°, the boat has no horizontal velocity of its own (vx = u + v cos 90° = 2.5 m/s).",
      "Step 3: Downstream drift distance: x = u × t_min = 2.5 m/s × 150 s = 375 m."
    ],
