    "id": "vbq-2024-dhaka-river-cross",
    "year": 2024,
    "board": "Dhaka",
    "paper": "Physics 1st Paper",
    "chapter": "Chapter 2: Vector (ভেক্টর)",
    "chapterNumber": 2,
    "vectorCategory": "riverboat",
