    "questionType": "CQ_Gha",
    "marks": 4,
    "difficulty": "Hard",
    "questionEn": "A river of width 750 m flows with current u = 2.5 m/s. A motorboat can travel at v = 5.0 m/s in still water. The boat captain must cross from station P to station Q directly opposite on the other bank. (a) Determine the heading angle α required to reach station Q directly. (b) If the boat captain instead steers at α = 90° to save crossing time, calculate the extra walking distance along the opposite bank required to reach station Q.",
    "questionBn": "750 m প্রশস্ত একটি নদীতে স্রোতের বেগ 2.5 m/s। একটি ইঞ্জিনচালিত নৌকা স্থির পানিতে 5.0 m/s বেগে চলতে পারে। মাঝিকে P ঘাট হতে সোজাসুজি বিপরীত ঘাট Q তে পৌঁছাতে হবে। (ক) Q ঘাটে সরাসরি পৌঁছাতে মাঝিকে কত কোণে নৌকা চালাতে হবে? (খ) মাঝি যদি সর্বনিম্ন সময়ে নদী পার হওয়ার জন্য 90° কোণে নৌকা চালায়, তবে পরবর্তীতে Q ঘাটে পৌঁছাতে তাকে পাড় দিয়ে কত দূর হাঁটতে হবে?",
    "relevantFormulaLatex": "\\cos\\alpha = -\\frac{u}{v}, \\quad x = u \\cdot t_{\\min} = u \\frac{d}{v}",
    "hintEn": "Part (a) uses cos α = -u/v. Part (b) uses t_min = d / v, and the walking distance equals the downstream drift distance x = u · t_min.",
    "hintBn": "ক অংশে cos α = -u/v দিয়ে দিক বের করো। খ অংশে t = d / v দিয়ে সময় বের করে ভাটির অপসরণ x = u × t নির্ণয় করো, যা হাঁটার দূরত্বের সমান।",
    "solutionStepsEn": [
      "Step 1: Part (a) - Directly opposite bank (zero drift):",
      "   cos α = -u / v = -2.5 / 5.0 = -0.5",
      "   α = arccos(-0.5) = 120° relative to downstream river current.",
      "Step 2: Part (b) - Minimum time crossing (α = 90°):",
      "   Crossing time: t_min = d / v = 750 / 5.0 = 150 seconds.",
      "Step 3: Downstream drift distance from station Q:",
      "   x = u × t_min = 2.5 × 150 = 375 meters.",
      "Step 4: Conclusion: The captain will land 375 m downstream from Q and must walk 375 m along the bank back to station Q."
    ],
    "solutionStepsBn": [
      "ধাপ ১: (ক) সোজাসুজি Q ঘাটে পৌঁছানোর শর্ত: cos α = -2.5 / 5.0 = -0.5  ==>  α = 120°",
      "ধাপ ২: (খ) সর্বনিম্ন সময়ের ক্ষেত্রে: t_min = 750 / 5 = 150 সেকেন্ড।",
      "ধাপ ৩: ভাটির অপসরণ: x = 2.5 × 150 = 375 m।",
      "ধাপ ৪: মাঝিকে Q ঘাটে পৌঁছাতে পাড় বরাবর 375 m হাঁটতে হবে।"
    ],
    "finalAnswerEn": "Heading angle α = 120°; Required walking distance along the bank = 375 meters.",
    "finalAnswerBn": "নৌকার দিক α = 120° এবং পাড় দিয়ে 375 m হাঁটতে হবে।",
    "examinerMarkingTips": "2 marks for heading angle calculation (120°), 2 marks for drift distance (375 m).",
    "commonMistakes": "Thinking walking distance is the hypotenuse of the triangle instead of purely the bank distance x.",
