    "questionEn": "What is an irrotational vector field?",
    "questionBn": "অঘূর্ণনশীল ভেক্টর ক্ষেত্র কাকে বলে?",
    "relevantFormulaLatex": "\\text{curl } \\vec{A} = \\nabla \\times \\vec{A} = \\vec{0}",
