      "ধাপ ৩: অবিচ্ছিন্ন দ্বিতীয় অন্তরজের জন্য মিশ্র অন্তরজ পরস্পর সমান হয়, ফলে প্রতিটি উপাংশ শূন্য হয়ে যায়।",
      "ধাপ ৪: সুতরাং ∇ × (∇φ) = 0।"
