    "questionEn": "A vector field is defined as A = (3x²y)i + (y²z)j - (2xz²)k. Determine the divergence of vector field A at the point P(1, 2, -1).",
    "questionBn": "একটি ভেক্টর ক্ষেত্র A = (3x²y)i + (y²z)j - (2xz²)k দেওয়া আছে। P(1, 2, -1) বিন্দুতে ভেক্টর ক্ষেত্রটির ডাইভারজেন্স নির্ণয় করো।",
    "relevantFormulaLatex": "\\nabla \\cdot \\vec{A} = \\frac{\\partial A_x}{\\partial x} + \\frac{\\partial A_y}{\\partial y} + \\frac{\\partial A_z}{\\partial z}",
    "hintEn": "Take partial derivatives w.r.t x, y, and z respectively, then substitute coordinates (1, 2, -1).",
    "hintBn": "আংশিক অন্তরজ নির্ণয় করে P(1, 2, -1) বিন্দুর মান বসাও।",
    "solutionStepsEn": [
      "Step 1: ∂Ax/∂x = ∂/∂x(3x²y) = 6xy",
      "Step 2: ∂Ay/∂y = ∂/∂y(y²z) = 2yz",
      "Step 3: ∂Az/∂z = ∂/∂z(-2xz²) = -4xz",
      "Step 4: Sum: ∇ · A = 6xy + 2yz - 4xz",
      "Step 5: Substitute P(1, 2, -1):",
      "   6(1)(2) + 2(2)(-1) - 4(1)(-1) = 12 - 4 + 4 = 12"
    ],
    "solutionStepsBn": [
      "ধাপ ১: ∂Ax/∂x = 6xy",
      "ধাপ ২: ∂Ay/∂y = 2yz",
      "ধাপ ৩: ∂Az/∂z = -4xz",
      "ধাপ ৪: ∇ · A = 6xy + 2yz - 4xz",
      "ধাপ ৫: P(1, 2, -1) বিন্দুতে মান = 6(1)(2) + 2(2)(-1) - 4(1)(-1) = 12 - 4 + 4 = 12"
    ],
    "finalAnswerEn": "Divergence ∇ · A at P(1, 2, -1) = 12 (positive outward flux).",
    "finalAnswerBn": "P(1, 2, -1) বিন্দুতে ∇ · A = 12।",
    "examinerMarkingTips": "1 mark for partial derivatives, 1 mark for substitution, 1 mark for final result 12.",
    "commonMistakes": "Including unit vectors i, j, k in the divergence answer (divergence is a scalar).",
    "verificationStatus": "Verified Official Board Paper",
    "sourceReference": "Rajshahi Board 2024, Physics 1st Paper, Question 3(c).",
    "parentCqId": "vbq-2024-rajshahi-cq",
    "cqSubpart": "ga",
    "languageVersion": "Bangla Version",
    "solutionVerified": true
