    "id": "vbq-2025-model-cross-torque",
    "year": 2025,
    "board": "Curriculum Practice",
    "paper": "Physics 1st Paper",
    "chapter": "Chapter 2: Vector (ভেক্টর)",
    "chapterNumber": 2,
    "vectorCategory": "dot-cross",
    "topicId": "topic-vector-dot-cross",
    "questionType": "CQ_Ga",
    "marks": 3,
    "difficulty": "Medium",
    "questionEn": "[2025 Curriculum Model Standard — Pre-Board Assessment] A force F = 4i - 3j + 5k N acts on a rigid body at a position vector r = 2i + 4j - k m from the pivot origin. Determine the torque τ acting on the body and calculate its magnitude.",
    "questionBn": "[২০২৫ শিক্ষাবর্ষের মডেল স্ট্যান্ডার্ড — প্রাক-বোর্ড মূল্যায়ন] একটি বস্তুর অবস্থান ভেক্টর r = 2i + 4j - k m এ একটি বল F = 4i - 3j + 5k N প্রযুক্ত হলো। মূলবিন্দুর সাপেক্ষে টর্ক τ এবং এর মান নির্ণয় করো।",
    "relevantFormulaLatex": "\\vec{\\tau} = \\vec{r} \\times \\vec{F} = \\begin{vmatrix} \\hat{i} & \\hat{j} & \\hat{k} \\\\ r_x & r_y & r_z \\\\ F_x & F_y & F_z \\end{vmatrix}",
    "hintEn": "Remember torque is r × F (NOT F × r). Set up the determinant with r in the second row and F in the third row.",
    "hintBn": "টর্ক হলো τ = r × F। নির্নায়কের দ্বিতীয় সারিতে r এবং তৃতীয় সারিতে F বসাও।",
    "solutionStepsEn": [
      "Step 1: Set up determinant: τ = | i  j  k ; 2  4 -1 ; 4 -3  5 |",
      "Step 2: i-component: (4)(5) - (-1)(-3) = 20 - 3 = 17 N·m",
      "Step 3: j-component: -[(2)(5) - (-1)(4)] = -[10 + 4] = -14 N·m",
      "Step 4: k-component: (2)(-3) - (4)(4) = -6 - 16 = -22 N·m",
      "Step 5: Torque vector: τ = 17i - 14j - 22k N·m",
      "Step 6: Magnitude: |τ| = √(17² + (-14)² + (-22)²) = √(289 + 196 + 484) = √969 ≈ 31.13 N·m"
    ],
    "solutionStepsBn": [
      "ধাপ ১: τ = r × F = | i j k ; 2 4 -1 ; 4 -3 5 |",
      "ধাপ ২: i(20 - 3) - j(10 + 4) + k(-6 - 16) = 17i - 14j - 22k N·m",
      "ধাপ ৩: মান = √(17² + 14² + 22²) = √969 ≈ 31.13 N·m"
    ],
    "finalAnswerEn": "Torque vector τ = 17i - 14j - 22k N·m; Magnitude |τ| = 31.13 N·m.",
    "finalAnswerBn": "টর্ক ভেক্টর τ = 17i - 14j - 22k N·m এবং মান 31.13 N·m।",
    "examinerMarkingTips": "1.5 marks for correct cross product expansion, 1.5 marks for magnitude and correct units (N·m).",
    "commonMistakes": "Computing F × r instead of r × F (reversing signs of all components).",
